<script setup lang="ts">
const auth=useAuth(),{notify,loginOpen}=useForum()
const statusNames:Record<string,string>={published:'已发布',hidden:'已隐藏',deleted:'已删除',active:'正常',disabled:'已禁用'},roleNames:Record<string,string>={member:'普通成员',admin:'管理员',super_admin:'超级管理员'}
const posts=ref<{id:string,title:string,status:string,pinned?:boolean,featured?:boolean}[]>([]),users=ref<{id:string,name:string,role:string,status:string}[]>([]),error=ref('')
const allowed=computed(()=>auth.user.value&&auth.user.value.role!=='member')
const replyItems=ref<{id:string,content:string,status:string,author:string}[]>([]),assets=ref<{id:string,status:string,width:number,height:number}[]>([])
async function load(){await auth.initialize();if(!allowed.value)return;try{posts.value=await auth.request('/admin/posts');replyItems.value=await auth.request('/admin/replies');assets.value=await auth.request('/admin/assets');if(auth.user.value?.role==='super_admin')users.value=await auth.request('/admin/users')}catch(e){error.value=(e as Error).message}}
async function editPost(id:string,patch:Record<string,unknown>){try{await auth.request('/posts/'+id,patch,'PATCH');await load();notify('内容状态已更新。')}catch(e){error.value=(e as Error).message}}
async function setUser(id:string,patch:Record<string,unknown>){try{await auth.request('/admin/users/'+id,patch,'PATCH');await load();notify('账号已更新。')}catch(e){error.value=(e as Error).message}}
async function hideAsset(id:string){try{await auth.request('/admin/assets/'+id,{},'DELETE');await load()}catch(e){error.value=(e as Error).message}}
async function moderateReply(id:string,status:string){try{await auth.request('/admin/replies/'+id,{status},'PATCH');await load()}catch(e){error.value=(e as Error).message}}
onMounted(load)
watch(()=>auth.user.value?.id,load)
</script>
<template><div class="award-admin-page"><h1>社区管理</h1><template v-if="allowed"><p class="award-field-help">内容管理与账号变更会记录操作日志。</p><NuxtLink to="/admin/awards" class="button secondary">十二橙器活动管理</NuxtLink><section class="award-admin-card"><h2>帖子管理</h2><article v-for="post in posts" :key="post.id" class="admin-content-row"><NuxtLink :to="'/post/'+post.id">{{ post.title }}</NuxtLink><span>{{ statusNames[post.status] }}</span><button @click="editPost(post.id,{status:post.status==='published'?'hidden':'published'})">{{ post.status==='published'?'隐藏':'恢复' }}</button><button @click="editPost(post.id,{pinned:!post.pinned})">{{ post.pinned?'取消置顶':'置顶' }}</button><button @click="editPost(post.id,{featured:!post.featured})">{{ post.featured?'取消精选':'精选' }}</button></article></section><section class="award-admin-card"><h2>回复管理</h2><article v-for="item in replyItems" :key="item.id" class="admin-content-row"><span>{{ item.author }}</span><p>{{ item.content }}</p><button @click="moderateReply(item.id,item.status==='published'?'hidden':'published')">{{ item.status==='published'?'隐藏':'恢复' }}</button></article></section><section class="award-admin-card"><h2>上传图片</h2><article v-for="asset in assets" :key="asset.id" class="admin-content-row"><img v-if="asset.status==='active'" :src="'/api/assets/'+asset.id" alt="上传图片" width="80" /><span>{{ asset.width }} × {{ asset.height }} · {{ statusNames[asset.status] }}</span><button v-if="asset.status==='active'" @click="hideAsset(asset.id)">隐藏图片</button></article></section><section v-if="auth.user.value?.role==='super_admin'" class="award-admin-card"><h2>账号管理</h2><article v-for="user in users" :key="user.id" class="admin-content-row"><strong>{{ user.name }}</strong><span>{{ roleNames[user.role] }} · {{ user.status==='deleted'?'已注销':statusNames[user.status] }}</span><button v-if="user.status!=='deleted'" @click="setUser(user.id,{status:user.status==='active'?'disabled':'active'})">{{ user.status==='active'?'禁用':'启用' }}</button></article><NuxtLink to="/admin/awards">前往活动管理中的“账号与权限”分配角色</NuxtLink></section></template><div v-else class="empty-state"><p>需要管理员账号。</p><button class="button primary" @click="loginOpen=true">登录</button></div><p v-if="error" class="form-error" role="alert">{{ error }}</p></div></template>
<style scoped>h1,h2{font-family:var(--serif);margin:1rem 0}.award-admin-card{margin-top:1rem}.admin-content-row{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;padding:.8rem 0;border-bottom:1px solid var(--line);font-size:.75rem}.admin-content-row>a,.admin-content-row>strong{flex:1;min-width:10rem}.admin-content-row>button{color:var(--orange);font-size:.65rem}.admin-content-row>span{color:var(--subtle);font-size:.65rem}</style>
